import type {TurnUsage} from './chatOrchestrator.js';

describe('TurnUsage', () => {
  it('carries total-turn token counts as inputTokens, outputTokens and totalTokens', () => {
    const usage: TurnUsage = {inputTokens: 3, outputTokens: 7, totalTokens: 10};
    expect(usage.inputTokens + usage.outputTokens).toBe(usage.totalTokens);
  });
});
